window.LL_COMPANION_DATA=JSON.parse(new TextDecoder().decode(fflate.gunzipSync(Uint8Array.from(atob(''),c=>c.charCodeAt(0)))));
/* Display wording only. Original engine explanations remain expandable. */
(function(){'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const positions={C:'catcher','1B':'first base','2B':'second base','3B':'third base',SS:'shortstop',LF:'left field',CF:'center field',RF:'right field',DH:'designated hitter',C2:'backup catcher','UTIL-IF':'backup infielder',OF4:'backup outfielder',FLEX:'flexible bench spot',BAT:'bench hitter'};
function lineupText(note){
 if(note.startsWith('Fan override'))return 'Your choice for this spot. The batting order adjusts around him.';
 if(note.startsWith('#1 ='))return 'Leads off for his mix of getting on base and speed, leaving the strongest hitters for the heart of the order.';
 if(note.startsWith('#2 ='))return 'Gets on base best among the remaining top hitters.';
 if(note.startsWith('#3 ='))return 'The lineup’s strongest hitter by batting production.';
 if(note.startsWith('#4 ='))return 'Brings the most power among the top hitters.';
 if(note.startsWith('#9 ='))return 'A second leadoff option to help set up the top of the order.';
 if(note.startsWith('#5 ='))return 'The next strongest hitter after the heart of the order.';
 if(note.startsWith('#6-8 ='))return 'The remaining hitters follow in order of batting production.';
 if(note.startsWith('next-best bat'))return 'Fills the next open spot by batting production after your selections.';
 return note.replace(/pinned by Joseph/g,'pinned by you');
}
function lineupNote(l){if(!l.note)return '';return `<div class="small muted">${esc(lineupText(l.note))}</div><details class="plain-details"><summary>How the order was calculated</summary><div class="small muted">${esc(l.note.replace(/pinned by Joseph/g,'pinned by you'))}</div></details>`;}
function reason(l){const pos=positions[l.slot]||l.slot;
 if(l.override==='Fan override'||/pinned by (Joseph|you)/i.test(l.fit))return `You chose him for ${pos}. The rest of the roster adjusts around your selection.`;
 if(l.slot==='DH')return 'Selected for his hitting and baserunning in the designated hitter spot.';
 if(['C','1B','2B','3B','SS','LF','CF','RF'].includes(l.slot))return `Selected for ${pos} based on his hitting, baserunning and defense, while fitting the rest of the roster.`;
 if(l.slot==='C2')return 'Adds a qualified backup catcher to the bench.';
 if(l.slot==='UTIL-IF')return 'Adds infield coverage to the bench.';
 if(l.slot==='OF4')return 'Adds outfield coverage to the bench.';
 if(['BAT','BAT2','BAT3'].includes(l.slot))return 'Adds another strong hitter to the bench.';
 if(l.slot==='FLEX')return 'Adds another bench option under the roster rules.';
 return `Selected for the ${pos} role under the roster rules.`;
}
function overrideText(l){const s=l.override||'';
 if(!s||s==='Fan override')return '';
 if(s.startsWith('DH glove rule:'))return 'Moving him into the field and the other player to DH improves the team overall.';
 if(s.includes('team-runs assignment uses him at'))return 'A higher-scoring alternative is used elsewhere to improve the whole lineup.';
 if(s.includes('most-played position')||s.includes('start guard'))return 'Another player scores higher here but does not meet the starting-position rules.';
 if(s.includes('but only'))return 'Another player scores higher here but has too little experience at this position.';
 return 'A roster rule affected this choice. See the calculation details below.';
}
function receipts(lg,cc){if(!lg.length&&!cc.length)return '<h3>Roster status</h3><div class="receipt"><p>Not currently on the 26-player roster.</p></div>';
 return '<h3>Why he was picked</h3>'+lg.map(l=>{const alt=String(l.fit||'').match(/^next eligible by value: (.+) [-+−]?\d/);return `<div class="receipt"><p><b>${esc(positions[l.slot]||l.slot)}</b> · ${esc(reason(l))}</p>${alt?`<p class="muted">Next eligible alternative: ${esc(alt[1])}.</p>`:''}${overrideText(l)?`<p>${esc(overrideText(l))}</p>`:''}${l.close?'<p><span class="tag cc">Close call</span> Another eligible option scored nearly as well.</p>':''}<details class="plain-details"><summary>See scores and selection rules</summary><p>${esc(l.need)}</p><p>${esc(l.score)}</p><p class="muted">${esc(String(l.fit||'').replace(/pinned by Joseph/g,'pinned by you'))}</p>${l.override?`<p>${esc(l.override)}</p>`:''}${l.close?`<p>${esc(l.close)}</p>`:''}</details></div>`;}).join('')+cc.filter(c=>!lg.some(l=>l.slot===c.slot)).map(c=>`<div class="receipt"><p><span class="tag cc">Close call</span> ${esc(c.pick)} and ${esc(c.alt)} scored nearly as well for ${esc(positions[c.slot]||c.slot)}.</p><details class="plain-details"><summary>See comparison scores</summary><p>${esc(c.pick)} ${c.pick_v} vs ${esc(c.alt)} ${c.alt_v} (${c.pct}%), ${esc(c.rule)}</p></details></div>`).join('');
}
document.addEventListener('click',e=>{if(e.target.closest('.lineup .plain-details'))e.stopPropagation();},true);
function bigMoments(b,kind,on,detailed){
 const october=!b.oct_G?'No postseason appearances in this franchise’s available records, so there is no October bonus.':b.d_oct>0?'His postseason performance earns an October bonus. Bigger series moments carry more weight.':'His overall postseason record adds no October bonus. It does not lower his score.';
 const best=b.oct_G&&b.oct_best_year&&b.oct_best_w>0?` His strongest postseason was ${Math.round(b.oct_best_year)}.`:'';
 let clutch;
 if(!b.clutch_PA&&!(kind==='p'&&b.sd_BF))clutch='The available records do not include enough play-by-play to assess his pressure performance.';
 else if(kind==='h')clutch=b.clutch_raw>0?'Performed better in pressure situations than his usual hitting would suggest.':b.clutch_raw<0?'Performed worse in pressure situations than his usual hitting would suggest.':'Performed as expected in pressure situations.';
 else clutch=b.d_cl>0?'His pressure performance adds to his pitching score.':b.d_cl<0?'His pressure performance lowers his pitching score.':'His pressure performance adds no adjustment to his pitching score.';
 const weight=b.clutch_PA||(kind==='p'&&b.sd_BF)?' This receives limited weight because pressure performance does not reliably carry from season to season.':'';
 const relief=kind==='p'&&b.sd_BF?'<p><b>Relief pressure performance.</b> Measures how he handled pressure beyond the credit already given for preventing runs. This replaces the regular Clutch measure for his relief appearances.</p>':'';
 return `<h3>Big Moments</h3><div class="receipt bmplain"><p><b>October.</b> ${october}${best}</p><p><b>Clutch.</b> ${clutch}${weight}</p>${relief}<p class="muted"><b>Big Moments is ${on?'ON':'OFF'}.</b> ${on?'These adjustments are included in the APEX scores used to build the roster.':'These results are for reference. Turn on Big Moments to include the adjustments in roster scoring.'}</p><details class="plain-details"><summary>See Big Moments scores and calculations</summary>${detailed.replace('<h3>Big Moments</h3>','')}</details></div>`;
}
function banner(html){return `<details class="banner bm bm-collapse"><summary><b>Big Moments ON</b> · Roster changes and scoring details</summary><div class="bm-banner-details">${html.replace(/^<div class="banner bm">/,'').replace(/<\/div>$/,'')}</div></details>`;}
window.LLPlain={lineupText,lineupNote,receipts,bigMoments,banner};
})();

/* Unpublished roster companion. Presentation only; never supplies engine inputs. */
(function(){'use strict';
const data=window.LL_COMPANION_DATA, esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=1)=>v===null||v===undefined||!Number.isFinite(v)?'Unavailable':v.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const positions=p=>['C','1B','2B','3B','SS','LF','CF','RF'].filter(x=>{const g=x==='LF'||x==='RF'?p.g_LF+p.g_RF:p['g_'+x];return g>0&&g>=p.elig_min;}).join(' / ');
const team=cur=>data.lsi.teams.find(t=>t.code===cur.t.code);
const metric=(cur,p,kind)=>team(cur)?.players.find(x=>x.id===p.id&&x.kind===(kind==='h'?'bat':'pit'));
let mode='h',query='',sort='apex',filter='',chosen=[],activeKey='';
const methodology=`<details><summary class="lsi-summary">How to read these scores · formula and coverage</summary><p>APEX remains the overall roster guide. Legacy Season Impact (LSI) offers a separate view of season-relative batting or pitching quality and sustained impact. Choose the view that fits your team; changing a sort never changes your roster.</p><p>Career quality weights each season's difference from its league by opportunities. Peak quality averages the best three qualifying quality seasons; peak impact averages the best three qualifying LSI seasons independently. Batting peak floor: 300 PA. Pitching: 100 IP for starters, 40 IP for relievers; unknown role uses 100 IP.</p><p>Batting event rate E = (.47 singles + .78 doubles + 1.09 triples + 1.40 HR + .33 unintentional BB + .34 HBP) ÷ (PA − IBB). LSI = 100 × (E − league E) × (PA − IBB) × [1 + .3 × min(1, G ÷ actual team G)]. Pitching D = (13 HR + 3 BB − 2 K) ÷ IP. LSI = 25 × (league D − D) × IP × [1 + .3 × min(1, IP ÷ actual team IP)]. Stint availability is opportunity weighted. Negative seasons stay negative.</p><p>LSI points are separate batting and pitching scales, with no defense, baserunning, park, replacement, postseason or military credit. Batting E is not wOBA. LSI has no WAR inputs, and is not Baseball Data Hub PIV. Its batting event weights share APEX's starting weights. No combined APEX + LSI score is calculated.</p><p>Lahman source ends in 2025. Pre-1955 batting career coverage is incomplete because required IBB/SF fields are missing; some APEX records extend into 2026. Incomplete career impact is withheld, with an available-season subtotal instead. Historical 1954 Retrosheet results are a separate labeled pilot and are not added to career totals. Missing values are never zeros. Lahman PA excludes unavailable catcher-interference events.</p></details>`;
function coverage(r){return r.complete?'Complete LSI coverage':`Partial LSI · ${r.validSeasons} scored seasons${r.missingYears?.length?' · missing '+r.missingYears.join(', '):''}`;}
function tiles(r){return `<div class="lsi-grid"><div><span>Career quality ${r.complete?'':'· available seasons'}</span><b>${fmt(r.careerQuality,4)}</b></div><div><span>Peak quality ${r.complete?'':'· available seasons'}</span><b>${fmt(r.peakQuality,4)}</b></div><div><span>Peak impact ${r.complete?'':'· available seasons'}</span><b>${fmt(r.peakImpact)}</b></div><div><span>Career impact</span><b>${fmt(r.careerImpact)}</b></div></div>${!r.complete?`<p class="lsi-coverage">Available-season subtotal: ${fmt(r.subtotal)} points. This is not full-career impact.</p>`:''}`;}
function raw(cur,p,kind){
 const rows=data.stats[cur.t.code+':'+(kind==='h'?'bat':'pit')+':'+p.id]||[];
 if(!rows.length)return '<p>Raw season statistics unavailable in this source.</p>';
 const cols=kind==='h'?['G','AB','R','H','2B','3B','HR','RBI','SB','CS','BB','SO','IBB','HBP','SH','SF']:['G','GS','W','L','SV','IPouts','H','ER','HR','BB','SO'];
 const value=(r,c)=>c==='IPouts'?r[c]===null?'Unavailable':Math.floor(r[c]/3)+'.'+r[c]%3:fmt(r[c],0);
 const totals={};cols.forEach(c=>totals[c]=rows.some(r=>r[c]===null)?null:rows.reduce((s,r)=>s+r[c],0));
 return `<details><summary class="lsi-summary">Franchise totals and every season · raw statistics</summary><p class="lsi-source">Lahman through 2025, full franchise scope. City assignment retains full franchise statistics. Missing season fields also make their franchise total unavailable. IP uses baseball notation: .1 = one out, .2 = two outs. Games sum franchise stints.</p><div class="scroll"><table><thead><tr><th>Year</th><th>Team IDs</th>${cols.map(c=>'<th class="n">'+(c==='IPouts'?'IP':c)+'</th>').join('')}</tr></thead><tbody><tr><td><b>Total</b></td><td>Franchise</td>${cols.map(c=>'<td class="n"><b>'+value(totals,c)+'</b></td>').join('')}</tr>${rows.map(r=>`<tr><td>${r.year}</td><td>${esc(r.teams)}</td>${cols.map(c=>'<td class="n">'+value(r,c)+'</td>').join('')}</tr>`).join('')}</tbody></table></div></details>`;
}
function historical(cur,p,kind){if(kind!=='h')return '';const r=data.pilot.players.find(x=>x.code===cur.t.code&&x.id===p.id);if(!r)return '';return `<details><summary class="lsi-summary">1954 historical pilot · ${fmt(r.seasonLSI)} LSI</summary><p>1954 only: quality ${fmt(r.quality,4)}, ${fmt(r.PA,0)} PA, availability ${fmt(r.availability,3)}. ${r.fullGames} recorded / ${r.deducedGames} reconstructed player-game lines.</p><p class="lsi-source">Retrosheet preferred records, including reconstructed games; the league baseline also includes reconstruction. This is not a complete historical career or an official-total reconciliation. ${r.finiganDiscrepancy?'Jim Finigan has an unresolved preferred-versus-official walk discrepancy. ':''}Philadelphia/Cardinals team games include the July 18 forfeit with no official player statistics. Separate from the Lahman career figures above.</p></details>`;}
function card(cur,p,kind){if(mode!==kind){mode=kind;chosen=[];filter='';}const r=metric(cur,p,kind);return `<section class="lsi-card"><div class="lsi-preview-label">Companion data</div><h3>Choose your view of ${esc(p.name)}</h3>${r?`<p class="lsi-source">${esc(coverage(r))} · Full franchise scope · ${kind==='h'?'Batting only':'Pitching only'}</p>${tiles(r)}<details><summary class="lsi-summary">LSI season breakdown</summary><div class="scroll"><table><thead><tr><th>Season</th><th>Quality vs league</th><th>LSI</th><th>Opportunities</th><th>Availability</th><th>Peak eligible</th></tr></thead><tbody>${r.seasons.map(s=>`<tr><td>${s.year}</td><td>${fmt(s.quality,4)}</td><td>${fmt(s.impact)}</td><td>${fmt(s.opportunities)}</td><td>${fmt(s.availability,3)}</td><td>${s.peakQualified?'Yes':'No'}${s.reason?' · '+esc(s.reason):''}</td></tr>`).join('')}</tbody></table></div></details>`:'<p>Companion data unavailable.</p>'}${raw(cur,p,kind)}${historical(cur,p,kind)}${methodology}<button class="btn" data-lsi-explore>Compare other candidates</button></section>`;}
function candidates(cur){return (mode==='h'?cur.t._S:cur.t._P).filter(p=>!query||p.name.toLowerCase().includes(query.toLowerCase())).filter(p=>!filter||(mode==='p'?(filter==='S'?p.sp_ok:p.rp_ok):filter==='DH'||positions(p).split(' / ').includes(filter))).map(p=>({p,r:metric(cur,p,mode)}));}
function comparison(cur){if(!chosen.length)return '<p class="small muted">Select up to two players to compare, then open a player to inspect eligibility and make your selection.</p>';return `<div class="lsi-compare">${chosen.map(id=>{const p=(mode==='h'?cur.t._S:cur.t._P).find(p=>p.id===id),r=p&&metric(cur,p,mode);return !p?'':`<article><h3>${esc(p.name)} <button class="btn" data-lsi-remove="${esc(id)}">Remove</button></h3><p>APEX ${fmt(p.total)} · ${mode==='h'?esc(positions(p)):`Starter ${fmt(p.SPx)} / Reliever ${fmt(p.RPx)}`}</p>${r?tiles(r):'Companion unavailable'}<button class="btn" data-lsi-open="${esc(id)}">Stats, eligibility & choose</button></article>`;}).join('')}</div>`;}
function drawRows(cur){const rows=candidates(cur);rows.sort((a,b)=>{const va=sort==='apex'?a.p.total:a.r?.[sort],vb=sort==='apex'?b.p.total:b.r?.[sort];const na=va===null||va===undefined,nb=vb===null||vb===undefined;return na!==nb?na-nb:na?a.p.name.localeCompare(b.p.name):vb-va||a.p.name.localeCompare(b.p.name);});return rows.map(({p,r})=>`<tr><td class="lsi-candidate-name"><b>${esc(p.name)}</b><div class="lsi-mobile-actions"><button class="btn" data-lsi-open="${esc(p.id)}">View / choose</button><button class="btn" data-lsi-compare="${esc(p.id)}" ${chosen.length>=2&&!chosen.includes(p.id)?'disabled':''}>${chosen.includes(p.id)?'Selected':'Compare'}</button></div><div class="small muted">${mode==='h'?esc(positions(p)):(p.sp_ok?'SP ':'')+(p.rp_ok?'RP':'')}${r?' · '+esc(coverage(r)):''}</div></td><td class="n">${fmt(p.total)}</td><td class="n">${fmt(r?.careerQuality,4)}</td><td class="n">${fmt(r?.peakQuality,4)}</td><td class="n">${fmt(r?.peakImpact)}</td><td class="n">${fmt(r?.careerImpact)}</td><td><div class="lsi-action"><button class="btn" data-lsi-open="${esc(p.id)}">View / choose</button><button class="btn" data-lsi-compare="${esc(p.id)}" ${chosen.length>=2&&!chosen.includes(p.id)?'disabled':''}>${chosen.includes(p.id)?'Selected':'Compare'}</button></div></td></tr>`).join('');}
function refresh(){const cur=window.LL_ROSTER.current();const body=document.querySelector('#lsi-rows');if(body)body.innerHTML=drawRows(cur);const compare=document.querySelector('#lsi-comparison');if(compare)compare.innerHTML=comparison(cur);}
function explore(){const cur=window.LL_ROSTER?.current();if(!cur)return;if(activeKey!==cur.t.key){chosen=[];query='';filter='';activeKey=cur.t.key;}document.querySelector('#mbody').innerHTML=`<div class="lsi-preview-label">Roster builder</div><h2>${esc(cur.t.short)} · Build your all-time team</h2><p>Compare overall APEX, sustained quality and peak impact. Your choices remain yours. Open a candidate for franchise stats, position values, season detail and the existing roster controls.</p><p class="small muted">${cur.city?'City pool with full-franchise credit':'Full franchise pool'} · Companion scores remain unchanged by Big Moments. Batting and pitching have separate LSI scales.</p><div class="lsi-tools"><select id="lsi-mode" aria-label="Player type"><option value="h" ${mode==='h'?'selected':''}>Hitters</option><option value="p" ${mode==='p'?'selected':''}>Pitchers</option></select><input id="lsi-search" type="search" placeholder="Find a player" aria-label="Find a player" value="${esc(query)}"><select id="lsi-filter" aria-label="Position or role"><option value="">All ${mode==='h'?'eligible positions':'roles'}</option>${(mode==='h'?['C','1B','2B','3B','SS','LF','CF','RF','DH']:['S','R']).map(x=>`<option value="${x}" ${filter===x?'selected':''}>${mode==='h'?x:x==='S'?'Starter eligible':'Reliever eligible'}</option>`).join('')}</select><select id="lsi-sort" aria-label="Comparison metric">${[['apex','Overall APEX'],['careerQuality','Career quality'],['peakQuality','Peak quality'],['peakImpact','Peak impact'],['careerImpact','Complete career impact']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>Sort: ${l}</option>`).join('')}</select></div><div id="lsi-comparison">${comparison(cur)}</div><div class="scroll lsi-table"><table><thead><tr><th>Candidate</th><th>APEX</th><th>Career quality</th><th>Peak quality</th><th>Peak impact</th><th>Career impact</th><th>Actions</th></tr></thead><tbody id="lsi-rows">${drawRows(cur)}</tbody></table></div>${methodology}`;document.querySelector('#modal').hidden=false;document.querySelector('#modal').scrollTop=0;}
function guide(){const app=document.querySelector('#app'),cur=window.LL_ROSTER?.current();if(!app||!cur||app.querySelector('.lsi-guide'))return;const guide=document.createElement('section');guide.className='lsi-guide';guide.innerHTML=`<div><div class="lsi-preview-label">Roster builder</div><h2 style="margin:5px 0">Your team. Your all-time roster.</h2><p>Find the fit: overall APEX, career quality, peak impact and season-by-season stats in one place.</p><small>Companion scores guide your choices. The approved roster engine and your overrides remain in control.</small></div><button class="btn" data-lsi-explore>Explore & compare players</button>`;app.prepend(guide);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-lsi-explore],[data-lsi-open],[data-lsi-compare],[data-lsi-remove]');if(!b)return;const cur=window.LL_ROSTER?.current();if(!cur)return;if(b.hasAttribute('data-lsi-explore'))explore();else if(b.dataset.lsiOpen){const p=(mode==='h'?cur.t._S:cur.t._P).find(p=>p.id===b.dataset.lsiOpen);if(p)window.LL_ROSTER.card(mode,p.name);}else if(b.dataset.lsiRemove){chosen=chosen.filter(id=>id!==b.dataset.lsiRemove);refresh();}else{const id=b.dataset.lsiCompare;chosen=chosen.includes(id)?chosen.filter(x=>x!==id):chosen.length<2?[...chosen,id]:chosen;refresh();}});
document.addEventListener('input',e=>{if(e.target.id==='lsi-search'){query=e.target.value;refresh();}});
document.addEventListener('change',e=>{if(e.target.id==='lsi-mode'){mode=e.target.value;chosen=[];filter='';explore();}if(e.target.id==='lsi-sort'){sort=e.target.value;refresh();}if(e.target.id==='lsi-filter'){filter=e.target.value;refresh();}});
window.LLCompanion={card,explore};
new MutationObserver(guide).observe(document.querySelector('#app'),{childList:true});setTimeout(guide,0);
})();

/* Capacity preference uses the existing fan-rule storage; no score changes. */
(function(){'use strict';
function install(){const root=document.querySelector('#app'),cur=window.LL_ROSTER?.current();if(!cur||!root||root.querySelector('.roster-balance'))return;
const size=cur.pins.rules?.bench_size||5,el=document.createElement('div');el.className='roster-balance tools';el.innerHTML=`<label>Roster balance <select id="roster-balance" aria-label="Roster balance"><option value="5" ${size===5?'selected':''}>Standard · 5 bench / 7 bullpen</option><option value="6" ${size===6?'selected':''}>6 bench / 6 bullpen</option><option value="7" ${size===7?'selected':''}>7 bench / 5 bullpen</option></select></label><span class="small muted">Five starters · 26 players when all spots can be filled</span><span id="roster-balance-warning" class="small" role="status"></span>`;
const guide=root.querySelector('.lsi-guide');if(guide)guide.after(el);else root.prepend(el);}
document.addEventListener('change',e=>{if(e.target.id!=='roster-balance')return;const size=Number(e.target.value),cur=LL_ROSTER.current(),penSize=12-size,raw=cur.raw,problems=[];
for(const [name,slot] of Object.entries(raw.roster||{}))if(slot==='BAT2'&&size<6||slot==='BAT3'&&size<7)problems.push(name+' in '+slot);
const pen=Object.entries(raw.staff||{}).filter(([,slot])=>slot!=='ROT');if(pen.length>penSize)problems.push(pen.length+' saved bullpen assignments');
for(const [name,slot] of pen)if(slot==='MID2'&&penSize<7||slot==='MID1'&&penSize<6)problems.push(name+' in '+slot);
if(problems.length){e.target.value=String(cur.pins.rules?.bench_size||5);document.querySelector('#roster-balance-warning').textContent='Move or clear these saved assignments before changing balance: '+problems.join('; ')+'. Your selections are preserved.';return;}
LL_ROSTER.setBalance(size);});
new MutationObserver(install).observe(document.querySelector('#app'),{childList:true});setTimeout(install,0);
})();
